import { RELEASE_IDS, releaseModule } from './release-config.js';
/**
 * Spec versions, canonical programs, and vendor release inputs.
 *
 * Real sources (BRIEF 9a/9b, core-model section 6):
 *   releases/<ver>/spec.json          (generated by `ehr spec-export`; else we call it)
 *   releases/<ver>/canonical.json     (v1 may also be programs/canonical/v0.json)
 *   releases/<ver>/RELEASE_NOTES.md
 *   lean/Ehr/Specs/<V1|V2|V3>.lean  (the reviewable spec module; the "Lean spec diff")
 * With EHR_FAKE=1 the fake fixtures are used instead, always (never mix the
 * fake checker with real content).
 */
import { existsSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import type { EhrClient } from './ehr.js';
import { FAKE_RELEASE_NOTES, fakeCanonical, fakeSpec } from './fake/fixtures.js';
import { programSchema, specSchema, type Program, type Spec } from './schema.js';
import { REPO_ROOT, readJson } from './util.js';

export interface Release {
  id: string;
  specVersion: string;
  spec: Spec;
  canonical: Program;
  personaCanonicals?: Record<string, Program>;
  notes: string;
  leanSpecSource: string | null;
  fake: boolean;
}


async function readText(file: string): Promise<string | null> {
  return existsSync(file) ? readFile(file, 'utf8') : null;
}

export async function loadRelease(id: string, ehr: EhrClient, root: string = REPO_ROOT): Promise<Release> {
  if (ehr.mode === 'fake') {
    return { id, specVersion: id, spec: fakeSpec(id), canonical: fakeCanonical(id), notes: FAKE_RELEASE_NOTES[id] ?? '', leanSpecSource: null, fake: true };
  }
  const dir = path.join(root, 'releases', id);
  const specFile = path.join(dir, 'spec.json');
  const spec = existsSync(specFile) ? await readJson(specFile, specSchema) : await ehr.specExport(id);
  const candidates = [path.join(dir, 'canonical.json'), ...(id === RELEASE_IDS.base ? [path.join(root, 'programs', 'canonical', 'v0.json')] : [])];
  const canonicalFile = candidates.find((f) => existsSync(f));
  if (!canonicalFile) throw new Error(`no canonical program for release ${id} (looked in ${candidates.join(', ')})`);
  const canonical = await readJson(canonicalFile, programSchema);
  const personaCanonicals: Record<string, Program> = {};
  for (const persona of ['P1', 'P2', 'P3', 'P4', 'P5']) {
    const file = path.join(dir, 'personas', `${persona}.json`);
    if (existsSync(file)) personaCanonicals[persona] = await readJson(file, programSchema);
  }
  const moduleName = releaseModule(id);
  const leanSpecSource = moduleName ? await readText(path.join(root, 'lean', 'Ehr', 'Specs', `${moduleName}.lean`)) : null;
  return { id, specVersion: id, spec, canonical, personaCanonicals, notes: (await readText(path.join(dir, 'RELEASE_NOTES.md'))) ?? '', leanSpecSource, fake: false };
}

/** Structural diff of two exported specs (what a release added or changed). */
export function specDiff(before: Spec, after: Spec): Record<string, unknown> {
  const byKey = <T>(xs: T[], key: (x: T) => string) => new Map(xs.map((x) => [key(x), x]));
  const added = <T>(a: T[], b: T[], key: (x: T) => string) => {
    const old = byKey(a, key);
    return b.filter((x) => !old.has(key(x)));
  };
  const removed = <T>(a: T[], b: T[], key: (x: T) => string) => added(b, a, key);
  const entryKey = (e: Spec['entries'][number]) => `${e.commit}/${e.element}/${JSON.stringify(e.when)}`;
  const reviewKey = (r: Spec['reviews'][number]) => `${r.commit}/${r.info}/${JSON.stringify(r.when)}`;
  return {
    from: before.version,
    to: after.version,
    addedElements: added(before.elements, after.elements, (e) => e.id),
    addedInfos: added(before.infos, after.infos, (e) => e.id),
    addedCommits: added(before.commits, after.commits, (e) => e.id),
    addedEntries: added(before.entries, after.entries, entryKey),
    addedReviews: added(before.reviews, after.reviews, reviewKey),
    addedAlerts: added(before.alerts, after.alerts, (a) => a.id),
    removedEntries: removed(before.entries, after.entries, entryKey),
    removedReviews: removed(before.reviews, after.reviews, reviewKey),
    catalogAdded: after.design.catalog.filter((k) => !before.design.catalog.includes(k)),
    designChanged: JSON.stringify(before.design) !== JSON.stringify(after.design),
  };
}

/** Use the vendor's role-safe projection; the all-role canonical is a template. */
export async function releaseForPersona(release: Release, persona: string, root: string = REPO_ROOT): Promise<Release> {
  if (release.fake) return release;
  const file = path.join(root, 'releases', release.id, 'personas', `${persona}.json`);
  return { ...release, canonical: await readJson(file, programSchema) };
}
